import gurobipy as gp
from gurobipy import GRB
products = []
profits = {}
requirements = {}
item_names = []
capacity = None
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('capacity.csv'):
        vals = rec['values']
        if 'resource_capacity' in vals:
            capacity = int(float(vals['resource_capacity']))
    elif rec['source'].endswith('products.csv'):
        vals = rec['values']
        name = vals['item_name']
        item_names.append(name)
        profits[name] = int(float(vals['item_value']))
        requirements[name] = int(float(vals['resource_requirement']))
if capacity is None:
    raise ValueError('Missing resource capacity in LEGACY_RECORDS')
if len(item_names) == 0 or set(item_names) != set(profits.keys()) or set(item_names) != set(requirements.keys()):
    raise ValueError('Missing or inconsistent product data in LEGACY_RECORDS')
m = gp.Model('BakeryOrder')
m.Params.MIPGap = 0.0001
x_vars = m.addVars(item_names, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((profits[name] * x_vars[name] for name in item_names)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((requirements[name] * x_vars[name] for name in item_names)) <= capacity, name='storage')
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in x_vars.values():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')